-- V4.9__fase1k_alertas_patch.sql
-- Creacin de tabla ALERTAS_ADMIN para la Fase 1K y expansin de RLS

BEGIN
   EXECUTE IMMEDIATE 'DROP TABLE "ALERTAS_ADMIN"';
EXCEPTION
   WHEN OTHERS THEN
      IF SQLCODE != -942 THEN
         RAISE;
      END IF;
END;
/

CREATE TABLE "ALERTAS_ADMIN" (
    "ID_ALERTA" NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY MINVALUE 1 MAXVALUE 9999999999999999999999999999 INCREMENT BY 1 START WITH 1 CACHE 20 NOORDER NOCYCLE NOKEEP NOSCALE NOT NULL ENABLE,
    "ID_PROPIEDAD" NUMBER NOT NULL ENABLE,
    "TIPO_ALERTA" VARCHAR2(50 CHAR) NOT NULL ENABLE,
    "NUMERO_APARTAMENTO" VARCHAR2(50 CHAR),
    "NOMBRE_RESIDENTE" VARCHAR2(100 CHAR),
    "ESTADO_CUOTA" VARCHAR2(50 CHAR),
    "LEIDA" CHAR(1 BYTE) DEFAULT 'N' NOT NULL ENABLE,
    "FECHA_CREACION" TIMESTAMP (6) WITH TIME ZONE DEFAULT FROM_TZ(CAST(SYSTIMESTAMP AS TIMESTAMP), 'America/Bogota') NOT NULL ENABLE,
    CONSTRAINT "PK_ALERTAS_ADMIN" PRIMARY KEY ("ID_ALERTA")
);

BEGIN
    DBMS_RLS.ADD_POLICY(
        object_schema   => USER,
        object_name     => 'ALERTAS_ADMIN',
        policy_name     => 'POL_RLS_PROP_ALERTAS',
        function_schema => USER,
        policy_function => 'PKG_SAED_SECURITY_RLS.FN_FILTRO_PROPIEDAD'
    );
END;
/
EXIT;
